query:
CREATE CONSTRAINT department_id IF NOT EXISTS FOR (n:Department) REQUIRE n.department_id IS UNIQUE;
CREATE CONSTRAINT ward_id       IF NOT EXISTS FOR (n:Ward)       REQUIRE n.ward_id IS UNIQUE;
CREATE CONSTRAINT patient_id    IF NOT EXISTS FOR (n:Patient)    REQUIRE n.patient_id IS UNIQUE;
CREATE CONSTRAINT admission_id  IF NOT EXISTS FOR (n:Admission)  REQUIRE n.admission_id IS UNIQUE;
CREATE CONSTRAINT specimen_id   IF NOT EXISTS FOR (n:Specimen)   REQUIRE n.specimen_id IS UNIQUE;
CREATE CONSTRAINT sample_id     IF NOT EXISTS FOR (n:Sample)     REQUIRE n.sample_id IS UNIQUE;
CREATE CONSTRAINT lab_result_id IF NOT EXISTS FOR (n:LabResult)  REQUIRE n.lab_id IS UNIQUE;
CREATE CONSTRAINT cbc_id        IF NOT EXISTS FOR (n:LabResult)  REQUIRE n.cbc_id IS UNIQUE;
CREATE CONSTRAINT antibiotic_id IF NOT EXISTS FOR (n:Antibiotic) REQUIRE n.antibiotic_id IS UNIQUE;
CREATE CONSTRAINT antibiotic_class IF NOT EXISTS FOR (n:AntibioticClass) REQUIRE n.name IS UNIQUE;
CREATE CONSTRAINT organism_taxid IF NOT EXISTS FOR (n:Organism)  REQUIRE n.taxid IS UNIQUE;
CREATE CONSTRAINT assembly_id   IF NOT EXISTS FOR (n:Assembly)   REQUIRE n.assembly_id IS UNIQUE;
CREATE CONSTRAINT gene_name     IF NOT EXISTS FOR (n:Gene)       REQUIRE n.name IS UNIQUE;
CREATE CONSTRAINT biodata_uri   IF NOT EXISTS FOR (n:BioDataFile) REQUIRE n.uri IS UNIQUE;
CREATE CONSTRAINT feature_locus IF NOT EXISTS FOR (n:Feature)    REQUIRE n.locus_tag IS UNIQUE;
CREATE CONSTRAINT vcr_id        IF NOT EXISTS FOR (n:VariantCallingRun) REQUIRE n.process_run_id IS UNIQUE;
CREATE CONSTRAINT variant_id    IF NOT EXISTS FOR (n:Variant)    REQUIRE n.variant_id IS UNIQUE;
CREATE CONSTRAINT snomed_sctid  IF NOT EXISTS FOR (n:SNOMED)     REQUIRE n.sctid IS NODE KEY;

:auto LOAD CSV WITH HEADERS FROM 'file:///clinical/Departments.csv' AS rec
CALL { WITH rec
  MERGE (d:Department {department_id: rec.department_id})
  SET d.name = rec.name, d.description = rec.description
} IN TRANSACTIONS OF 500 ROWS;

:auto LOAD CSV WITH HEADERS FROM 'file:///clinical/Antibiotic.csv' AS rec
CALL { WITH rec
  MERGE (ab:Antibiotic {antibiotic_id: rec.antibiotic_id})
  SET ab.name = rec.name, ab.abbreviation = rec.abbreviation,
      ab.class = rec.class, ab.description = rec.description
} IN TRANSACTIONS OF 500 ROWS;

:auto LOAD CSV WITH HEADERS FROM 'file:///clinical/Organisms.csv' AS rec
CALL { WITH rec
  MERGE (o:Organism {taxid: rec.taxid})
  SET o.sciname = rec.sciname, o.snomed_sctid = rec.snomed_sctid
} IN TRANSACTIONS OF 500 ROWS;

MATCH path = (:Department)<-[:BELONGS_TO]-(:Ward)<-[:ADMITTED_TO]-(:Admission)<-[:HAS_ADMISSION]-(p:Patient)
OPTIONAL MATCH collected = (p)<-[:COLLECTED_FROM]-(:Specimen)
RETURN path, collected;

MATCH path = (ac:AntibioticClass)<-[:BELONGS_TO]-(:Antibiotic)<-[:AGAINST]-(:LabResult:MIC)<-[:TESTED_FOR]-(sp:Specimen)
MATCH isolate = (sp)<-[:DERIVED_FROM]-(:Sample)-[:IDENTIFIED_AS]->(:Organism)
RETURN path, isolate;

MATCH pc = (p:Patient)-[:HAS_DISORDER|HAS_CLINICAL_FINDING|HAS_CLINICAL_HISTORY]->(:SNOMED)
OPTIONAL MATCH ac = (p)-[:HAS_ADMISSION]->(:Admission)-[:HAS_PRINCIPAL_DIAGNOSIS|USE_DEVICE]->(:SNOMED)
RETURN pc, ac;

MATCH spine = (:Patient)<-[:COLLECTED_FROM]-(:Specimen)<-[:DERIVED_FROM]-(s:Sample)-[:HAS_ASSEMBLY]->(:Assembly)
OPTIONAL MATCH org = (s)-[:IDENTIFIED_AS]->(:Organism)
RETURN spine, org;

MATCH genes = (s:Sample)-[:HAS_ASSEMBLY]->(:Assembly)-[:FOUND]->(:Gene)
OPTIONAL MATCH variants = (s)-[:HAS]->(:VariantCallingRun)-[:CALLED]->(:Variant)-[:AFFECTS]->(:Feature)
RETURN genes, variants;
